const keepIfEqual=(current,next)=>JSON.stringify(current)===JSON.stringify(next)?current:next;
const sessionKey='autodeskai.session.token';
const themeKey='autodeskai.theme';
const readTheme=()=>{try{const saved=window.localStorage.getItem(themeKey);return saved==='dark'||saved==='light'?saved:window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}catch{return'light'}};
document.documentElement.dataset.theme=readTheme();
const readStoredToken=()=>{try{return window.sessionStorage.getItem(sessionKey)||''}catch{return''}};
const storeToken=value=>{try{if(value)window.sessionStorage.setItem(sessionKey,value);else window.sessionStorage.removeItem(sessionKey)}catch{/* Private browsing can block storage. */}};
const chatStorage=()=>{try{return window.sessionStorage}catch{return null}};

const label=x=>(x||'PENDING').replaceAll('_',' ');
const title=x=>({SOFTWARE_INSTALL:'Software Installation',ACCESS_REQUEST:'Application Access',PASSWORD_RESET:'Password Reset',PASSWORD_CHANGE:'Password Change',CLARIFICATION:'More Information Needed'}[x.intent]||'IT Support Request');
const icon=x=>x.intent==='SOFTWARE_INSTALL'?MonitorDown:x.intent==='ACCESS_REQUEST'?Grid2X2:x.intent?.startsWith('PASSWORD_')?KeyRound:Ticket;
const initials=x=>(x||'User').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const parseDate=value=>new Date(/(?:Z|[+-]\d{2}:\d{2})$/i.test(value)?value:value+'Z');
const formatDate=value=>{if(!value)return'—';const date=parseDate(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString();};
const formatShortDate=value=>{if(!value)return'—';const date=parseDate(value);return Number.isNaN(date.getTime())?'—':date.toLocaleDateString();};
const deviceOnline=device=>{const lastSeen=parseDate(device.last_seen);return device.status==='ACTIVE'&&!Number.isNaN(lastSeen.getTime())&&Date.now()-lastSeen.getTime()<=120000;};
const employeeClosableStatuses=new Set(['COMPLETED','FAILED','AWAITING_USER_ACTION','APPROVED_PROVISIONING_REQUIRED']);
const oldestOpenTicket=rows=>[...rows].reverse().find(row=>!['CLOSED','REJECTED'].includes(row.status));

