 const[busy,setBusy]=useState(false),[error,setError]=useState(''),[retryUntil,setRetryUntil]=useState(0),[retryTick,setRetryTick]=useState(0),[modal,setModal]=useState(null),[admin,setAdmin]=useState({users:[],requests:[],devices:[],audit:[]}),[accessPending,setAccessPending]=useState([]),[catalog,setCatalog]=useState({software:[],applications:[]}),[enrollment,setEnrollment]=useState(null),[authRole,setAuthRole]=useState('employee');
 const session=useRef(token),employeePoll=useRef(null),adminPoll=useRef(null),pageHistory=useRef({pages:['Dashboard'],index:0}),actionVersion=useRef(0),acting=useRef(false),chatOwnerRef=useRef(null);
