   const loadRows=(name,path)=>async signal=>{if(name==='audit'&&activeRef.current!=='Audit Logs')return;const rows=await api(path,{signal});if(!signal.aborted&&session.current===token){setAdmin(current=>{const next=keepIfEqual(current[name],rows);return next===current[name]?current:{...current,[name]:next}});clearBackendError()}};
